// --- Lógica para procesar los datos de la entrevista ---

// Obtenemos el primer item de la entrada (los datos de la hoja de cálculo)
// CAMBIO: Se usa $items('main')[0].json para referenciar la entrada por nombre ('main'), lo cual es más robusto.
const interviewData = $items('Get row(s) in sheet')[0].json;

// --- 1. Lógica para calcular la próxima fecha de entrevista ---

const dayMap = {
  'domingo': 0, 'lunes': 1, 'martes': 2, 'miércoles': 3, 'miercoles': 3, 
  'jueves': 4, 'viernes': 5, 'sábado': 6
};

// Se agrega una verificación para asegurar que HORARIO no sea nulo
const horario = (interviewData.HORARIO || '').toLowerCase();

// Expresiones regulares para extraer días y horas
const dayRegex = /de (lunes|martes|miércoles|miercoles|jueves|viernes|sábado|domingo) a (lunes|martes|miércoles|miercoles|jueves|viernes|sábado|domingo)/;
const timeRegex = /(\d{1,2}:\d{2}\s?(am|pm))/g;

const dayMatch = horario.match(dayRegex);
const timeMatches = horario.match(timeRegex);

let confirmationSentence = "No se pudo determinar un horario. Favor de verificar el formato en la celda 'HORARIO'.";

if (dayMatch && timeMatches) {
  const startDay = dayMap[dayMatch[1]];
  const endDay = dayMap[dayMatch[2]];
  const interviewStartTime = timeMatches[0];

  let interviewDate = new Date();
  // Empezamos a buscar desde mañana
  interviewDate.setDate(interviewDate.getDate() + 1);
  interviewDate.setHours(0, 0, 0, 0);

  let foundDate = false;
  // Buscamos en los próximos 14 días por una fecha disponible
  for (let i = 0; i < 14; i++) {
    let currentDayOfWeek = interviewDate.getDay();

    if (currentDayOfWeek >= startDay && currentDayOfWeek <= endDay) {
      foundDate = true;
      break;
    }
    interviewDate.setDate(interviewDate.getDate() + 1);
  }

  if (foundDate) {
    // Formateamos la fecha a un formato amigable en español (ej: miércoles 8 de abril)
    const options = { weekday: 'long', day: 'numeric', month: 'long' };
    const formattedDate = interviewDate.toLocaleDateString('es-ES', options);

    // Construimos la oración de confirmación
    confirmationSentence = `Te confirmamos tu entrevista para el día ${formattedDate} a las ${interviewStartTime}`;
  } else {
    confirmationSentence = "No se encontraron fechas disponibles en las próximas 2 semanas."
  }
}

// --- 2. Lógica para formatear las listas (documentos, importante, notas) ---
const formatList = (text) => {
  if (!text) return '';
  // Reemplaza las comas con saltos de línea y quita espacios extra
  return text.split(',').map(s => `• ${s.trim()}`).join('\n');
}

// --- 3. Preparamos el objeto de salida ---

// Copiamos los datos originales
const output = { ...interviewData };

// Añadimos los nuevos campos formateados
output.formattedConfirmation = confirmationSentence;
output.formattedDocuments = formatList(interviewData["DOCUMENTACION A PRESENTAR"]);
output.formattedImportant = formatList(interviewData.IMPORTANTE);
output.formattedNote = formatList(interviewData.NOTA);

// Devolvemos el resultado para que el siguiente nodo lo pueda usar
return output;

